// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 preVal, uint256 postVal, address actor) public {
        vm.assume(actor != address(0));
        // set an initial MinSum before initialization
        vm.prank(actor);
        c.SetMinSum(preVal);
        // freeze configuration
        vm.prank(actor);
        c.Initialized();
        // invariant: after initialization, SetMinSum has no effect on MinSum
        vm.prank(actor);
        c.SetMinSum(postVal);
        assertTrue(c.MinSum() == preVal);
    }
}

