pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        v1 = bound(v1, 0, type(uint128).max);
        v2 = bound(v2, 0, type(uint128).max);
        vm.assume(v1 != v2);

        // set MinSum legitimately, before initialization
        c.SetMinSum(v1);
        c.Initialized();

        // after initialization the reference reverts on SetMinSum; swallow it safely
        try c.SetMinSum(v2) { /* mutant path */ } catch { /* reference path */ }

        // MinSum must still be v1 in the reference; the mutant returns v2
        assertTrue(c.MinSum() == v1);
    }
}

