pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val) public {
        val = bound(val, 0, type(uint256).max - 1);
        address actor = address(0x1234);
        vm.prank(actor);
        try c.SetMinSum(val) {
            // General rule: MinSum always equals the exact argument passed to SetMinSum.
            assertEq(c.MinSum(), val);
        } catch {
            // Should not revert before initialization.
            assertTrue(false);
        }
    }
}

